/**
 * Shadow chunk — CODE-SPLIT.
 *
 * A registered chunk manifest module (see MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs): the one place the shadow-map shaders are
 * imported, and the one legal import site for the shadow generators. Loaded
 * only through `import()` from the shadow rig, the first time a light in the
 * world asks to cast shadows — a world without one never fetches it, and the
 * main bundle stays flat.
 *
 * The GLSL shaders ride in the chunk (WebGL2 is the floor); the WGSL pair is
 * loaded only when the WebGPU engine is in use, like the other chunks. Each
 * specifier here is mirrored in `optimizeDeps.include` in vite.config.ts.
 */
import '@babylonjs/core/Shaders/shadowMap.vertex';
import '@babylonjs/core/Shaders/shadowMap.fragment';
import '@babylonjs/core/Shaders/depthBoxBlur.fragment';
import '@babylonjs/core/Shaders/ShadersInclude/shadowMapFragmentSoftTransparentShadow';

export { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';
export { CascadedShadowGenerator } from '@babylonjs/core/Lights/Shadows/cascadedShadowGenerator';

/** The WGSL shadow shaders, for the WebGPU engine only. */
export async function loadWebGPUShadowShaders(): Promise<void> {
  await Promise.all([
    import('@babylonjs/core/ShadersWGSL/shadowMap.vertex'),
    import('@babylonjs/core/ShadersWGSL/shadowMap.fragment'),
    import('@babylonjs/core/ShadersWGSL/depthBoxBlur.fragment'),
    import('@babylonjs/core/ShadersWGSL/ShadersInclude/shadowMapFragmentSoftTransparentShadow'),
  ]);
}

export type ShadowChunkModule = {
  ShadowGenerator: typeof import('@babylonjs/core/Lights/Shadows/shadowGenerator').ShadowGenerator;
  CascadedShadowGenerator: typeof import('@babylonjs/core/Lights/Shadows/cascadedShadowGenerator').CascadedShadowGenerator;
  loadWebGPUShadowShaders: typeof loadWebGPUShadowShaders;
};
